          ]
        }
      ]
    },
    {
      "id": "E2",
      "title": "Support zero-quantity pantry rows",
      "stories": [
        {
          "id": "S3",
          "statement": "Remove the quantity > 0 constraint so a pantry row can exist at zero quantity.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "an existing pantry row", "when": "its quantity is updated to 0", "then": "the row persists rather than being deleted or rejected"},
            {"id": "AC2", "given": "a pantry row reaches zero quantity through normal use decrements", "when": "the update is saved", "then": "the ingredient remains present in the pantry data"}
          ]
        },
        {
          "id": "S4",
          "statement": "Render an out-of-stock state for pantry rows at zero quantity.",
          "domains": ["ux"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a pantry row with quantity 0", "when": "/pantry renders", "then": "the row shows an out-of-stock indicator instead of a numeric quantity"},
            {"id": "AC2", "given": "a pantry row with quantity greater than 0", "when": "/pantry renders", "then": "no out-of-stock indicator is shown for that row"}
          ]
        }
      ]
    },
    {
      "id": "E3",
      "title": "One-step custom item creation from the pantry page",
      "stories": [
        {
          "id": "S5",
          "statement": "Add a \"Create custom item\" entry point on /pantry that opens a single creation form.",
          "domains": ["ux"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a user is on /pantry", "when": "the page renders", "then": "a \"Create custom item\" button is visible"},
            {"id": "AC2", "given": "a user clicks \"Create custom item\"", "when": "the form opens", "then": "it captures name, the optional product-identity fields, and an initial quantity in a single form"}
          ]
        },
        {
          "id": "S6",
          "statement": "Create the custom ingredient and its pantry row together in one Server Action.",
          "domains": ["backend", "ux"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a valid submission from the create-custom-item form", "when": "the Server Action runs", "then": "the ingredient and its pantry row are both created in a single transaction"},
            {"id": "AC2", "given": "a submitted barcode duplicates an existing ingredient's barcode", "when": "the Server Action runs", "then": "neither the ingredient nor the pantry row is created and an inline error is returned to the form"},
            {"id": "AC3", "given": "the Server Action completes successfully", "when": "control returns to /pantry", "then": "the new row appears in the pantry list without a separate manual navigation step"}
          ]
        }
      ]
    },
    {
      "id": "E4",
      "title": "Surface product identity on ingredient detail",
      "stories": [
        {
          "id": "S7",
          "statement": "Display product-identity fields on /pantry/[id] when they are present on the ingredient.",
          "domains": ["ux"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "an ingredient with brand, barcode, packageQuantity, and packageUnit set", "when": "/pantry/[id] renders", "then": "those fields are displayed on the page"},
            {"id": "AC2", "given": "an ingredient with none of the product-identity fields set", "when": "/pantry/[id] renders", "then": "no empty or placeholder product-identity fields are shown"}
          ]
        }
      ]
    }
  ]
}

