            {"id": "AC7", "given": "a pantry item with quantity 0", "when": "/pantry is rendered", "then": "the item appears with an \"out of stock\" indicator instead of being hidden or causing an error"},
            {"id": "AC8", "given": "a pantry item with quantity 0", "when": "/pantry/[id] is opened", "then": "the page displays an \"out of stock\" state"}
          ]
        }
      ]
    },
    {
      "id": "E3",
      "title": "Create custom branded items in one step from the pantry",
      "stories": [
        {
          "id": "S4",
          "statement": "As a pantry owner, I want a \"Create custom item\" entry point on /pantry so I don't have to leave the page to add a new product.",
          "domains": ["ux"],
          "acceptance_criteria": [
            {"id": "AC9", "given": "a user on /pantry", "when": "the page loads", "then": "a \"Create custom item\" button is visible"},
            {"id": "AC10", "given": "a user clicks \"Create custom item\"", "when": "the action is triggered", "then": "a one-step creation form opens without navigating away from /pantry"}
          ]
        },
        {
          "id": "S5",
          "statement": "As a pantry owner, I want the one-step form to capture the same product-identity fields as the ingredient form so branded products get full identity in a single step.",
          "domains": ["ux"],
          "acceptance_criteria": [
            {"id": "AC11", "given": "the one-step create form is open", "when": "it renders", "then": "it includes fields for ingredient name, an initial pantry quantity, and optional brand, barcode, packageQuantity, and packageUnit"},
            {"id": "AC12", "given": "a user fills in only the required ingredient name and leaves the optional product-identity fields blank", "when": "the form is submitted", "then": "the submission succeeds without requiring those optional fields"}
          ]
        },
        {
          "id": "S6",
          "statement": "As a pantry owner, I want the custom ingredient and its pantry row created together in one Server Action so the two-step flow collapses into one atomic operation.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC13", "given": "valid form input including a new ingredient name and an initial quantity", "when": "the one-step Server Action runs", "then": "it creates both the custom ingredient and its pantry row in a single action"},
            {"id": "AC14", "given": "the Server Action creating the ingredient and pantry row", "when": "the ingredient insert succeeds but the pantry row insert fails", "then": "neither record is left persisted"},
            {"id": "AC15", "given": "a submitted barcode that collides with an existing ingredient's barcode", "when": "the Server Action runs", "then": "it returns a validation error and creates neither the ingredient nor the pantry row"}
          ]
        }
      ]
    },
    {
      "id": "E4",
      "title": "Extend the ingredient form with product-identity fields",
      "stories": [
        {
          "id": "S7",
          "statement": "As a pantry owner, I want the standalone ingredient form to capture the same optional product-identity fields so ingredients created there also carry brand, barcode, and package size.",
          "domains": ["ux"],
          "acceptance_criteria": [
            {"id": "AC16", "given": "the ingredient form at /ingredients/new", "when": "it renders", "then": "it includes optional inputs for brand, barcode, packageQuantity, and packageUnit alongside the existing fields"},
            {"id": "AC17", "given": "the ingredient form submitted with no product-identity fields filled in", "when": "it is submitted", "then": "the ingredient is created successfully with those fields left empty"}
          ]
        }
      ]
    },
    {
      "id": "E5",
      "title": "Surface product identity on the pantry item detail page",
      "stories": [
        {
          "id": "S8",
          "statement": "As a pantry owner, I want /pantry/[id] to show an item's brand, barcode, and package size when known so I can confirm I'm looking at the right branded product.",
          "domains": ["ux"],
          "acceptance_criteria": [
            {"id": "AC18", "given": "a pantry item whose ingredient has brand, barcode, packageQuantity, and packageUnit all set", "when": "/pantry/[id] is viewed", "then": "all four values are displayed on the page"},
            {"id": "AC19", "given": "a pantry item whose ingredient has none of the product-identity fields set", "when": "/pantry/[id] is viewed", "then": "those fields are omitted from the page rather than shown as blank placeholders"}
          ]
        }
      ]
    }
  ]
}

