{
  "item": "HM-40",
  "epics": [
    {
      "id": "E1",
      "title": "Request authentication for REST and gRPC",
      "stories": [
        {
          "id": "S1",
          "statement": "As the platform, I authenticate every REST and gRPC request from a bearer token or API key so that the caller's identity is known before any resource access.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a request carries a valid bearer token or API key", "when": "the request is processed", "then": "it resolves to a Principal(tenantId, scopes) that downstream handlers can use"},
            {"id": "AC2", "given": "a request to a protected endpoint carries no credential or an invalid one", "when": "the request is processed", "then": "the request is rejected with an unauthenticated error before reaching business logic"},
            {"id": "AC3", "given": "a gRPC call carries a bearer token or API key in call metadata", "when": "the call is received", "then": "it is authenticated through the same credential-resolution path as REST, producing an equivalent Principal"}
          ]
        },
        {
          "id": "S2",
          "statement": "As an operator, I configure API keys as salted hashes so that raw credentials are never stored or logged in recoverable form.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "an API key is configured for a tenant", "when": "it is persisted", "then": "only a salted hash of the key is stored, never the plaintext key"},
            {"id": "AC2", "given": "an incoming request presents a raw API key", "when": "it is checked against configured credentials", "then": "it is verified by hashing and comparing, without the plaintext ever being logged or echoed"},
            {"id": "AC3", "given": "an API key is configured with malformed or missing hash material", "when": "the service loads configuration", "then": "the service fails fast at startup with an actionable error rather than accepting the entry"}
          ]
        }
      ]
    },
    {
      "id": "E2",
      "title": "Tenant isolation by transparent resource namespacing",
      "stories": [
        {
          "id": "S1",
          "statement": "As the platform, I namespace topic and subscription resource ids by tenant at the API boundary so that tenants never see each other's resource identifiers.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "an authenticated Principal with a tenantId creates a topic by name", "when": "the resource is created", "then": "its internal id is transparently namespaced by tenantId without the caller needing to supply any tenant qualifier"},
            {"id": "AC2", "given": "two different tenants each create a topic with the same logical name", "when": "both creations complete", "then": "they resolve to distinct namespaced resources with no collision or cross-visibility"}
          ]
        },
        {
          "id": "S2",
          "statement": "As a tenant, I can only list, publish to, or read topics and subscriptions that belong to my own tenant so that cross-tenant access is impossible by construction.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a Principal for tenant A requests a topic or subscription owned by tenant B", "when": "the request is processed", "then": "it is rejected as not found, with no information disclosed about tenant B's resource"},
            {"id": "AC2", "given": "a Principal for tenant A lists topics or subscriptions", "when": "the listing is returned", "then": "it contains only resources namespaced under tenant A"},
            {"id": "AC3", "given": "a Principal for tenant A attempts to read a subscription backlog belonging to tenant B", "when": "the read is attempted", "then": "access is denied and no backlog data is returned"}
          ]
        }
      ]
    },
    {
      "id": "E3",
      "title": "Scope-based admin authorization and public probe endpoints",
      "stories": [
        {
          "id": "S1",
          "statement": "As an operator, I require an admin scope for administrative operations so that only elevated principals can perform destructive or tenant-wide actions.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a Principal without an admin scope calls an admin operation such as deleting a topic", "when": "the request is processed", "then": "it is rejected with a forbidden error and the operation does not execute"},
            {"id": "AC2", "given": "a Principal with an admin scope calls an admin operation", "when": "the request is processed", "then": "the operation executes within the Principal's own tenant scope"}
          ]
        },
        {
          "id": "S2",
          "statement": "As an operator, I expose /health and /metrics without authentication so that probes and scrapers keep working under the new auth model.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "authentication is enabled for the service", "when": "a request is made to /health with no credentials", "then": "the request succeeds and returns health status"},
            {"id": "AC2", "given": "authentication is enabled for the service", "when": "a request is made to /metrics with no credentials", "then": "the request succeeds and returns metrics"}
          ]
        }
      ]
    },
    {
      "id": "E4",
      "title": "Configurable auth mode with dev and backward-compatible fallback",
      "stories": [
        {
          "id": "S1",
          "statement": "As an operator, I get fail-fast startup validation of auth configuration so that misconfiguration is caught before the service accepts traffic.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "the auth configuration is invalid or incomplete (e.g. malformed key entries, unresolvable scopes)", "when": "the service starts", "then": "startup fails immediately with a clear error identifying the configuration problem"},
            {"id": "AC2", "given": "a valid auth configuration", "when": "the service starts", "then": "it starts normally and begins enforcing authentication on protected endpoints"}
          ]
        },
        {
          "id": "S2",
          "statement": "As a developer or operator of an existing single-tenant deployment, I can run with auth disabled under a default tenant so that local dev and pre-existing journals keep working unchanged.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "auth is disabled in configuration", "when": "any request is made without credentials", "then": "the request is processed under a fixed default tenant without a credential check"},
            {"id": "AC2", "given": "an existing single-tenant journal created before tenant isolation existed", "when": "the service runs in auth-disabled default-tenant mode", "then": "the existing resources remain accessible under the default tenant exactly as before"},
            {"id": "AC3", "given": "auth is disabled", "when": "admin operations are invoked under the default tenant", "then": "they are permitted without scope checks, consistent with the single-tenant dev/back-compat intent"}
          ]
        }
      ]
    }
  ]
}

