            {"id": "AC2", "given": "a running cluster", "when": "a new replica is started", "then": "it joins the existing cluster automatically and appears as an Up member within the configured join timeout"},
            {"id": "AC3", "given": "a replica process", "when": "it starts", "then": "it exposes a management HTTP port serving bootstrap and health endpoints"}
          ]
        },
        {
          "id": "S2",
          "statement": "As an operator, I want a keep-majority split-brain resolver configured, so that the cluster automatically downs minority partitions during a network split instead of leaving the system in a split-brain state.",
          "domains": ["backend", "infra"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a running cluster partitioned into two unequal groups by a network split", "when": "the split-brain resolver's stable-after period elapses", "then": "the minority-side partition is downed and removed from the cluster while the majority side remains Up"},
            {"id": "AC2", "given": "a network split producing two equal-sized partitions", "when": "the split-brain resolver evaluates the partitions", "then": "it applies the configured tie-breaking rule deterministically so exactly one side survives"},
            {"id": "AC3", "given": "a cluster with the split-brain resolver enabled", "when": "no network partition is present", "then": "normal node removal (graceful shutdown or crash) is handled by the resolver without erroneously downing healthy nodes"}
          ]
        },
        {
          "id": "S3",
          "statement": "As an operator, I want cluster health and membership state observable via the management HTTP port, so that I can verify cluster status during rollout and incident response.",
          "domains": ["infra"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a running cluster node", "when": "I query the management HTTP health endpoint", "then": "it returns the node's readiness and liveness status reflecting actual cluster membership state"},
            {"id": "AC2", "given": "a running cluster", "when": "I query the management HTTP cluster-members endpoint on any node", "then": "it returns the full current membership list with each member's status (Up, Joining, Leaving, Down)"}
          ]
        }
      ]
    },
    {
      "id": "E2",
      "title": "Cluster Sharding for bucket entities",
      "stories": [
        {
          "id": "S1",
          "statement": "As a developer, I want bucket entities hosted via Cluster Sharding instead of the node-local BucketEntityManager, so that each bucket is addressable cluster-wide and load is distributed across nodes.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a bucket entity that previously lived in the node-local BucketEntityManager", "when": "the service is deployed with Cluster Sharding enabled", "then": "the entity is hosted by the shard region and reachable via an EntityRef regardless of which node receives the request"},
            {"id": "AC2", "given": "a client holding an EntityRef for a bucket id", "when": "it sends a command", "then": "the command is routed to the single active instance of that bucket entity cluster-wide, with no duplicate instances running concurrently"},
            {"id": "AC3", "given": "the BucketEntityManager code path", "when": "the Cluster Sharding migration is complete", "then": "the node-local BucketEntityManager is removed and no longer referenced"}
          ]
        },
        {
          "id": "S2",
          "statement": "As a developer, I want existing persistence ids and the journal to remain unchanged by the sharding migration, so that existing bucket event history and recovery continue to work without a data migration.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a bucket entity with existing persisted events under its current persistence id", "when": "it is rehosted under Cluster Sharding", "then": "it recovers its full event history unchanged and produces the same state as before the migration"},
            {"id": "AC2", "given": "the sharded entity implementation", "when": "comparing persistence id derivation to the pre-sharding implementation", "then": "the persistence id for a given bucket is identical, and the configured journal plugin is unchanged"}
          ]
        },
        {
          "id": "S3",
          "statement": "As an operator, I want bucket entities to rebalance across nodes when cluster membership changes, so that load is redistributed after scale-out or node failure without manual intervention.",
          "domains": ["backend", "infra"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "a running cluster with bucket shards distributed across existing nodes", "when": "a new node joins", "then": "the shard coordinator rebalances a subset of shards onto the new node over time without entity data loss"},
            {"id": "AC2", "given": "a node hosting active bucket entities", "when": "that node crashes or leaves the cluster", "then": "its shards are reassigned to surviving nodes and affected bucket entities recover from the journal and resume handling commands"}
          ]
        }
      ]
    },
    {
      "id": "E3",
      "title": "Distributed projection via ShardedDaemonProcess",
      "stories": [
        {
          "id": "S1",
          "statement": "As a developer, I want the single-instance projection replaced by a ShardedDaemonProcess split into N slice ranges, so that projection processing is distributed across the cluster instead of running on one node.",
          "domains": ["backend"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "the service is deployed as a cluster", "when": "the projection ShardedDaemonProcess starts", "then": "exactly N projection worker instances are created, each assigned a distinct, non-overlapping slice range covering the full persistence id slice space"},
            {"id": "AC2", "given": "the N projection workers running across cluster nodes", "when": "events are written across all slice ranges", "then": "every event is processed exactly once by the worker owning its slice range, with no gaps and no duplicate processing across workers"}
          ]
        },
        {
          "id": "S2",
          "statement": "As an operator, I want projection workers to rebalance across nodes when cluster membership changes, so that projection processing continues and redistributes after scale-out or node failure.",
          "domains": ["backend", "infra"],
          "acceptance_criteria": [
            {"id": "AC1", "given": "N projection workers distributed across the current cluster nodes", "when": "a node hosting one or more workers leaves the cluster", "then": "the ShardedDaemonProcess reassigns the affected slice ranges to surviving nodes and processing resumes from the last recorded offset for each range"},
            {"id": "AC2", "given": "a running cluster with projection workers distributed across existing nodes", "when": "a new node joins", "then": "the ShardedDaemonProcess rebalances a subset of slice-range workers onto the new node"}
          ]
        }
      ]
    }
  ]
